from django.contrib.sitemaps import Sitemap
from .models import CustomerNDAContract

class SignedContractSitemap(Sitemap):
    changefreq = 'never'
    priority = 0.3

    def items(self):
        # Only expose boilerplate public templates; private client contracts must NEVER be listed in sitemaps
        return CustomerNDAContract.objects.filter(is_signed=True, is_public_sample_template=True)

    def location(self, item):
        return f"/agreements/public-templates/{item.slug}/"
